INSERT INTO `hotfixes`.`spell` (`ID`, `NameSubtext`, `Description`, `AuraDescription`, `VerifiedBuild`) VALUES
(1403000, '', 'Call a burning fragment of the sky down upon the target area, scorching everything beneath it.', 'Call a burning fragment of the sky down upon the target area, scorching everything beneath it.', 69933),
(1403001, '', 'Wrap an ally in a mantle of Firelands flame. The ward absorbs damage and sears those who strike it.', 'Wrap an ally in a mantle of Firelands flame. The ward absorbs damage and sears those who strike it.', 69933),
(1403002, '', 'Leap to a target location and crash down in a burst of flame, burning nearby enemies.', 'Leap to a target location and crash down in a burst of flame, burning nearby enemies.', 69933),
(1403003, '', 'Warm an ally with an everliving ember, mending their wounds.', 'Warm an ally with an everliving ember, mending their wounds.', 69933),
(1403004, '', 'Exhale a wave of scorching air in front of you, burning and disorienting enemies caught in it.', 'Exhale a wave of scorching air in front of you, burning and disorienting enemies caught in it.', 69933),
(1403005, '', 'Ignite a circle of cinders at the target location, burning all who linger inside.', 'Ignite a circle of cinders at the target location, burning all who linger inside.', 69933),
(1403006, '', 'Encase yourself in cooling magma that absorbs damage and sears attackers.', 'Encase yourself in cooling magma that absorbs damage and sears attackers.', 69933),
(1403007, '', 'Gather a surge of fire and hurl it at the target in a blast fit for the Firelord.', 'Gather a surge of fire and hurl it at the target in a blast fit for the Firelord.', 69933),
(1403010, '', 'Fire courses through your veins, increasing your spell haste by 5%.', 'Fire courses through your veins, increasing your spell haste by 5%.', 69933),
(1403011, '', 'A lifetime beside the forge hardens your flames, increasing your Fire damage by 5%.', 'A lifetime beside the forge hardens your flames, increasing your Fire damage by 5%.', 69933);
